mapper.select:
SELECT COUNT(1) FROM product p LEFT JOIN product_category pc ON p.category_id = pc.category_id LEFT JOIN brand b ON p.brand = b.brand_id WHERE 1=1 AND p.audit_status = 1 -- 审核通过 AND p.is_on_shelf = 1 -- 已上架
AND p.product_type = #{productType}
AND p.price BETWEEN 0 AND 50
AND p.price BETWEEN 50 AND 100
AND p.price BETWEEN 100 AND 200
AND p.price > 200
AND pc.category_code IN
#{code}
AND p.brand = #{brand}
AND pc.category_code = #{type}
AND (b.brand_name LIKE CONCAT('%', #{keyword}, '%') OR p.model LIKE CONCAT('%', #{keyword}, '%'))
AND p.product_type = 1
AND p.product_type = 2
AND p.`condition` = #{condition}

SELECT 1
FROM product p
WHERE p.product_id = #{productId}

SELECT p.product_id AS productId, p.model, p.brand, b.brand_name AS brandName, p.product_type AS productType, p.price, p.stock, p.audit_status AS auditStatus, p.create_time AS createTime FROM product p LEFT JOIN brand b ON p.brand = b.brand_id WHERE p.audit_status = #{auditStatus}
AND LOWER(p.model) LIKE CONCAT('%', LOWER(#{productName}), '%')
AND (LOWER(b.brand_name) LIKE CONCAT('%', LOWER(#{brand}), '%') OR p.brand = #{brand})
AND LOWER(p.model) LIKE CONCAT('%', LOWER(#{model}), '%')
AND p.product_type = #{productType}
ORDER BY p.create_time DESC
